/**
 * Immediate on/off setting (`design/components/switch.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/switch.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import * as zag from '@zag-js/switch'
import { normalizeProps } from '@zag-js/solid'

import {
  agentMember,
  claimSlot,
  createDerived,
  elementRef,
  useDirection,
  useMachine,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/switch.module.css'

export interface SwitchProps {
  'aria-describedby'?: string
  'aria-label'?: string
  /**
   * Names the switch from a label elsewhere on the page, such as `SettingsRow`'s row label,
   * which is one label for a whole row rather than one per control.
   */
  'aria-labelledby'?: string
  'aria-required'?: boolean
  checked?: boolean
  defaultChecked?: boolean
  disabled?: boolean
  id?: string
  /**
   * Visible inline label. Omit it only when the context labels the switch, and then `aria-label`
   * is required.
   */
  label?: string
  name?: string
  onCheckedChange?: (checked: boolean) => void
  value?: string
}

/** Immediate on/off setting. */
export default function Switch(given: SwitchProps): JSX.Element {
  const props = mergeProps(
    { disabled: false } as Defaults<SwitchProps, 'disabled'>,
    claimSlot(given, 'row-labelled'),
  )
  const uid = createUniqueId()
  const track = elementRef<HTMLElement>()
  const documentDirection = useDirection(() => track.value)
  const service = useMachine(
    zag.machine,
    () =>
      ({
        id: uid,
        dir: documentDirection(),
        checked: props.checked,
        defaultChecked: props.defaultChecked,
        disabled: props.disabled,
        required: props['aria-required'],
        name: props.name,
        value: props.value,
        onCheckedChange: (details) => {
          props.onCheckedChange?.(details.checked)
        },
      }) as Partial<zag.Props>,
  )
  const api = createDerived(() => zag.connect(service, normalizeProps))
  const dataState = createDerived(() => (api.value.checked ? 'on' : 'off'))
  let release1: (() => void) | undefined
  const effect1 = () => {
    release1?.()
    const ran = agentMember({
      member: 'Switch',
      element: () => track.value,
      state: () => ({ checked: api.value.checked, disabled: props.disabled }),
      actions: {
        check: () => api.value.setChecked(true),
        uncheck: () => api.value.setChecked(false),
      },
    })
    release1 = () => {
      ran()
    }
  }
  onMount(effect1)
  onCleanup(() => release1?.())
  return (
    <>
      {props.label === undefined ? (
        <button
          class={styles.track}
          type="button"
          role="switch"
          id={props.id}
          aria-checked={api.value.checked}
          disabled={props.disabled}
          aria-label={props['aria-label']}
          aria-labelledby={props['aria-labelledby']}
          aria-describedby={props['aria-describedby']}
          aria-required={props['aria-required']}
          data-state={dataState.value}
          data-disabled={props.disabled ? '' : undefined}
          data-required={props['aria-required'] ? '' : undefined}
          data-member="switch"
          onclick={() => api.value.toggleChecked()}
          ref={track.attach}
        >
          {/* thumb */}
          <span class={styles.thumb} data-state={dataState.value} />
        </button>
      ) : (
        <label
          class={styles.row}
          data-state={dataState.value}
          data-disabled={props.disabled ? '' : undefined}
          data-required={props['aria-required'] ? '' : undefined}
          data-member="switch"
        >
          {/* track */}
          <button
            class={styles.track}
            type="button"
            role="switch"
            id={props.id}
            aria-checked={api.value.checked}
            disabled={props.disabled}
            aria-label={props['aria-label']}
            aria-labelledby={props['aria-labelledby']}
            aria-describedby={props['aria-describedby']}
            aria-required={props['aria-required']}
            data-state={dataState.value}
            data-disabled={props.disabled ? '' : undefined}
            data-required={props['aria-required'] ? '' : undefined}
            data-member="switch"
            onclick={() => api.value.toggleChecked()}
            ref={track.attach}
          >
            {/* thumb */}
            <span class={styles.thumb} data-state={dataState.value} />
          </button>
          {/* label */}
          <span class={styles.label}>{props.label}</span>
        </label>
      )}
      {props.name !== undefined && api.value.checked ? (
        <input type="hidden" name={props.name} value={props.value ?? 'on'} />
      ) : null}
    </>
  )
}

Switch.controlKind = 'row-labelled'
